    if (movies != null) {
      map['movies'] = movies?.map((v) => v.toJson()).toList();
    }
    return map;
  }
  MovieDataEntity toMovieData(){
    return MovieDataEntity(pageNumber: pageNumber, limit: limit, movies: movies?.map((e) => e.toMovieEntity(),).toList());
}
}